import React, { useState, useEffect } from "react";
import { Box, Typography, Button, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper } from "@mui/material";
import { useNavigate } from "react-router-dom";

// Mock election results (replace with dynamic data from backend)
const mockResults = [
  { position: "President", candidate: "John Doe", votes: 150 },
  { position: "Vice President", candidate: "Jane Smith", votes: 120 },
  { position: "Secretary", candidate: "Alice Johnson", votes: 90 },
];

const ResultsPage = () => {
  const navigate = useNavigate();
  const [results, setResults] = useState([]);
  const [electionEnded, setElectionEnded] = useState(false);

  // Simulate election end check (replace with actual logic)
  useEffect(() => {
    const electionEndDate = new Date("2025-03-16T00:00:00").getTime();
    const now = new Date().getTime();
    if (now > electionEndDate) {
      setElectionEnded(true);
      setResults(mockResults); // Simulate fetching results
    }
  }, []);

  return (
    <Box sx={{ textAlign: "center", p: 4 }}>
      <Typography variant="h4" fontWeight="bold" mb={4}>
        Election Results
      </Typography>

      {!electionEnded ? (
        <Box>
          <Typography variant="h6" color="text.secondary" mb={3}>
            The election has not ended yet. No results are available at this time.
          </Typography>
          <Button
            variant="contained"
            color="primary"
            onClick={() => navigate("/dashboard/vote")}
            sx={{ mt: 2, px: 4, py: 1.5, fontSize: "16px" }}
            aria-label="Go to Voting Page"
          >
            Go to Voting Page
          </Button>
        </Box>
      ) : results.length === 0 ? (
        <Typography variant="h6" color="text.secondary">
          No results to display.
        </Typography>
      ) : (
        <TableContainer component={Paper} sx={{ maxWidth: 800, margin: "0 auto", mt: 4 }}>
          <Table aria-label="Election Results Table">
            <TableHead>
              <TableRow>
                <TableCell sx={{ fontWeight: "bold" }}>Position</TableCell>
                <TableCell sx={{ fontWeight: "bold" }}>Candidate</TableCell>
                <TableCell sx={{ fontWeight: "bold" }} align="right">Votes</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {results.map((result, index) => (
                <TableRow key={index}>
                  <TableCell>{result.position}</TableCell>
                  <TableCell>{result.candidate}</TableCell>
                  <TableCell align="right">{result.votes}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </Box>
  );
};

export default ResultsPage;
